def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    rows = {}
    cols = {}
    for r, c in points:
        rows.setdefault(r, []).append(c)
        cols.setdefault(c, []).append(r)
    top = min(r for r, c in points)
    bottom = max(r for r, c in points)
    left = min(c for r, c in points)
    right = max(c for r, c in points)
    out = [row[:] for row in grid]
    def paint(r, c):
        if out[r][c] == bg:
            out[r][c] = 2
    # Complete the outside rectangle around the marked pattern.
    for c in range(left, right + 1):
        paint(top, c)
        paint(bottom, c)
    for r in range(top, bottom + 1):
        paint(r, left)
        paint(r, right)
    # Complete long interior vertical dividers across the rectangle.
    for c, rs in cols.items():
        if left < c < right and len(rs) >= 4:
            for r in range(top, bottom + 1):
                paint(r, c)
    # An interior horizontal divider is indicated by a run plus a larger break.
    for r, cs in rows.items():
        if top < r < bottom and len(cs) >= 3:
            cs = sorted(cs)
            has_run = any(b == a + 1 for a, b in zip(cs, cs[1:]))
            has_large_gap = any(b - a > 2 for a, b in zip(cs, cs[1:]))
            if has_run and has_large_gap:
                for c in range(cs[0], cs[-1] + 1):
                    paint(r, c)
    return out
